type RawTemplate = Omit<EnterpriseProviderTemplate, "models" | "apiKeyManagementUrl"> & {
  models: EnterpriseModelMetadata[];
  apiKeyManagementUrl?: string;
};

const TEMPLATES: Record<string, RawTemplate> = JSON.parse(RAW_TEMPLATES) as Record<
  string,
  RawTemplate
>;

export const ENTERPRISE_PROVIDER_TEMPLATES: EnterpriseProviderTemplate[] = Object.entries(
  TEMPLATES,
).map(([templateId, template]) => ({
  templateId,
  nameZh: template.nameZh,
  nameEn: template.nameEn,
  apiType: template.apiType,
  baseUrl: template.baseUrl,
  models: template.models,
  ...(template.apiKeyManagementUrl
    ? { apiKeyManagementUrl: template.apiKeyManagementUrl }
    : {}),
}));

/** 喂给原生 ProviderTemplatePicker 的视图:config 不被选择器消费,留空对象即可。 */
export function enterprisePickerTemplates(): ProviderSettingsTemplateView[] {
  return ENTERPRISE_PROVIDER_TEMPLATES.map((template) => ({
    templateId: template.templateId,
    templateNameMap: { "zh-CN": template.nameZh, "en-US": template.nameEn },
    config: {},
  }));
}

/** 按模板 id 取预填字段;未收录的 id 返回 null(走自定义表单)。 */
export function enterpriseTemplatePrefill(templateId: string): EnterpriseProviderTemplate | null {
  return (
    ENTERPRISE_PROVIDER_TEMPLATES.find((item) => item.templateId === templateId) ?? null
  );
}
